<?php $pageTitle='Add Book';require __DIR__.'/../../includes/librarian-layout.php';$cats=db()->query('SELECT id,name,parent_id FROM categories ORDER BY name')->fetchAll();$authors=db()->query('SELECT id,name FROM authors ORDER BY name')->fetchAll();$errors=[];if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$title=trim($_POST['title']??'');$desc=trim($_POST['description']??'');$categoryIds=array_values(array_unique(array_filter(array_map('intval',$_POST['categories']??[]))));$publisher=trim($_POST['publisher']??'');$year=$_POST['publication_year']!==''?(int)$_POST['publication_year']:null;$isbn=trim($_POST['isbn']??'');$language=trim($_POST['language']??'English');$status=in_array($_POST['status']??'', ['draft','published','archived'],true)?$_POST['status']:'draft';$authorIds=array_map('intval',$_POST['authors']??[]);$file=$_FILES['book_file']??null;$cover=$_FILES['cover_image']??null;if(strlen($title)<1||strlen($title)>255)$errors[]='Title is required.';if(!$categoryIds)$errors[]='At least one category is required.';if($year!==null&&($year<1000||$year>(int)date('Y')+1))$errors[]='Invalid publication year.';if(!$file||$file['error']!==UPLOAD_ERR_OK)$errors[]='A book file is required.';$ext=$file?strtolower(pathinfo($file['name'],PATHINFO_EXTENSION)):'';$type=file_type_from_ext($ext);$max=(int)setting('max_upload_mb',DEFAULT_MAX_UPLOAD_MB)*1024*1024;if($file&&$file['size']>$max)$errors[]='File exceeds the configured size limit.';if($file&&!in_array($type,allowed_file_types(),true))$errors[]='This file type is not currently allowed.';if($file&&$type==='pdf'){$fh=@fopen($file['tmp_name'],'rb');$sig=$fh?fread($fh,5):'';if($fh)fclose($fh);if($sig!=='%PDF-')$errors[]='The uploaded file is not a valid PDF signature.';}if(!$errors){$pdo=db();$dest=null;$coverPath=null;$pdo->beginTransaction();try{$slug=unique_slug($title);$s=$pdo->prepare('INSERT INTO books(title,slug,description,publisher,publication_year,isbn,language,status,added_by) VALUES(?,?,?,?,?,?,?,?,?)');$s->execute([$title,$slug,$desc,$publisher,$year,$isbn,$language,$status,(int)current_user()['id']]);$bookId=(int)$pdo->lastInsertId();$cs=$pdo->prepare('INSERT INTO book_categories(book_id,category_id) VALUES(?,?)');foreach($categoryIds as $cid)$cs->execute([$bookId,$cid]);foreach($authorIds as $aid){$s=$pdo->prepare('INSERT IGNORE INTO book_authors(book_id,author_id) VALUES(?,?)');$s->execute([$bookId,$aid]);}$stored=bin2hex(random_bytes(16)).'.'.$ext;if(!is_dir(UPLOAD_DIR)&&!mkdir(UPLOAD_DIR,0755,true)&&!is_dir(UPLOAD_DIR))throw new RuntimeException('Upload directory unavailable.');$dest=UPLOAD_DIR.DIRECTORY_SEPARATOR.$stored;if(!move_uploaded_file($file['tmp_name'],$dest))throw new RuntimeException('Could not save uploaded file.');$hash=hash_file('sha256',$dest);$relative=UPLOAD_WEB_PATH.'/'.$stored;$s=$pdo->prepare('INSERT INTO book_files(book_id,file_name,file_path,file_type,file_size,file_hash,is_main) VALUES(?,?,?,?,?,?,1)');$s->execute([$bookId,basename($file['name']),$relative,$type,(int)$file['size'],$hash]);$coverPath=save_cover_upload($cover);if($coverPath)$pdo->prepare('UPDATE books SET cover_image=? WHERE id=?')->execute([$coverPath,$bookId]);$pdo->commit();log_activity((int)current_user()['id'],'create_book','book',$bookId);flash('success','Book created successfully.');redirect('librarian/books/index.php');}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();if($dest&&is_file($dest))@unlink($dest);if($coverPath)delete_stored_file($coverPath);$errors[]='Could not create the book. Check the database and upload directory.';}}} ?><section class="section"><div class="form-card"><h1>Add Book</h1><?php foreach($errors as $err):?><div class="alert error"><?=e($err)?></div><?php endforeach;?><form method="post" enctype="multipart/form-data" class="form-grid"><?=csrf_field()?><div class="field full"><label>Title</label><input name="title" required maxlength="255" value="<?=old('title')?>"></div><div class="field full"><label>Description</label><textarea name="description"><?=old('description')?></textarea></div><div class="field"><label>Categories</label><select name="categories[]" required multiple size="6"><?php foreach($cats as $c):?><option value="<?=$c['id']?>"><?=e($c['name'])?></option><?php endforeach;?></select></div><div class="field"><label>Authors</label><select name="authors[]" multiple size="5"><?php foreach($authors as $a):?><option value="<?=$a['id']?>"><?=e($a['name'])?></option><?php endforeach;?></select></div><div class="field"><label>Publisher</label><input name="publisher"></div><div class="field"><label>Publication year</label><input type="number" name="publication_year" min="1000" max="2100"></div><div class="field"><label>ISBN</label><input name="isbn" maxlength="30"></div><div class="field"><label>Language</label><input name="language" value="English" maxlength="50"></div><div class="field"><label>Status</label><select name="status"><option value="draft">Draft</option><option value="published">Published</option><option value="archived">Archived</option></select></div><div class="field"><label>Book file (PDF only)</label><input type="file" name="book_file" required accept=".pdf"><small class="muted">PDF · Max <?=e((string)setting('max_upload_mb',20))?> MB</small></div><div class="field"><label>Optional cover</label><input type="file" name="cover_image" accept=".jpg,.jpeg,.png,.webp"><small class="muted">JPG, PNG or WebP · Max 5 MB</small></div><div><button class="btn">Create book</button></div></form></div></section><?php require __DIR__.'/../../includes/panel-footer.php';?>
